// Longest match wins, so two-character operators are listed before the
// one-character ones they would otherwise shadow.
const PUNCTUATORS = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

