    return this.pos + offset >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.pos + offset]
  }

  here() {
    return { line: this.line, column: this.column }
  }

  advance() {
    const ch = this.chars[this.pos]
    this.pos++
    if (ch === '\n') {
      this.line++
      this.column = 1
    } else if (ch === '\t') {
      this.column = Math.floor((this.column - 1) / TAB_WIDTH) * TAB_WIDTH + TAB_WIDTH + 1
    } else {
      this.column++
    }
