        }
      }
    }

    let trailing = false
    while (isIdentPart(this.peek())) {
      this.advance()
      trailing = true
    }

    const text = this.chars.slice(from, this.pos).join('')
    if (prefixHadNoDigits || trailing) {
      this.fail(start, `invalid number ${text}`)
    }
    return { kind: 'number', text, line: start.line, column: start.column }
  }

