        continue
      }
      value += this.advance()
    }
    return { kind: 'string', text: JSON.stringify(value), line: start.line, column: start.column }
  }

  scanEscape() {
    const backslashPos = this.here()
    this.advance() // backslash
    const ch = this.peek()
    switch (ch) {
      case 'n':
        this.advance()
        return '\n'
      case 't':
        this.advance()
        return '\t'
      case 'r':
        this.advance()
        return '\r'
      case '\\':
        this.advance()
        return '\\'
      case '"':
        this.advance()
        return '"'
      case '0':
        this.advance()
        return '\0'
      case 'x': {
        this.advance()
        const h1 = this.peek()
        const h2 = this.peek(1)
        if (!isHexDigit(h1) || !isHexDigit(h2)) this.fail(backslashPos, 'invalid escape \\x')
        this.advance()
        this.advance()
        return String.fromCharCode(parseInt(h1 + h2, 16))
