 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { scan, LexError } from './lexer.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  // eslint-disable-next-line no-constant-condition
  while (true) {
    let bytesRead
    try {
      bytesRead = require('node:fs').readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const source = readStdin()

  let tokens
  try {
    tokens = scan(source)
  } catch (err) {
    if (err instanceof LexError) {
      process.stderr.write(`error: ${err.line}:${err.column}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  let out = ''
  if (mode === 'tokens') {
    for (const tok of tokens) {
      out += `${tok.line}:${tok.column} ${tok.kind} ${tok.text}\n`
    }
  } else {
    const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
    for (const tok of tokens) counts[tok.kind]++
    for (const kind of STAT_KINDS) out += `${kind} ${counts[kind]}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
  process.exit(0)
}

main()
"}

